import { Suspense } from 'react'
import { notFound } from 'next/navigation'
import { getProduct, getRelatedProducts } from '@/lib/products'

async function ProductDetails({
  slug,
  searchParams,
}: {
  slug: string
  searchParams: Promise<{ currency?: string }>
}) {
  const { currency = 'USD' } = await searchParams
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
    </>
  )
}

async function RelatedProducts({ slug }: { slug: string }) {
  const related = await getRelatedProducts(slug)

  return (
    <section>
      <h2>Related products</h2>
      {related.map((item) => (
        <p key={item.slug}>{item.name}</p>
      ))}
    </section>
  )
}

export default async function ProductPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string }>
}) {
  const { slug } = await params

  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense
        fallback={
          <>
            <h1>Loading product…</h1>
            <p>Loading price…</p>
          </>
        }
      >
        <ProductDetails slug={slug} searchParams={searchParams} />
      </Suspense>
      <Suspense fallback={<p>Loading related products…</p>}>
        <RelatedProducts slug={slug} />
      </Suspense>
    </main>
  )
}

import { Suspense } from 'react'
import { notFound } from 'next/navigation'
import { getProduct, getRelatedProducts } from '@/lib/products'

async function ProductDetails({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string }>
}) {
  const { slug } = await params
  const { currency = 'USD' } = await searchParams
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
    </>
  )
}

async function RelatedProducts({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params
  const related = await getRelatedProducts(slug)

  return (
    <>
      {related.map((item) => (
        <p key={item.slug}>{item.name}</p>
      ))}
    </>
  )
}

export default function ProductPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string }>
}) {
  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense
        fallback={
          <>
            <h1>Loading product…</h1>
            <p>Loading price…</p>
          </>
        }
      >
        <ProductDetails params={params} searchParams={searchParams} />
      </Suspense>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products…</p>}>
          <RelatedProducts params={params} />
        </Suspense>
      </section>
    </main>
  )
}
